/* ============================================================
   أطياب الجاسم (React) — صفحة وكلائنا (BranchesPage)

   تخطيط اللابتوب (حسب رسم المالك وتعليماته):
     · أسفل الهيدر بـ10px ليبل «وكلاءنا»، وتحته بـ5px أزرار الدول.
     · صفّ: إطار فاخر يساراً بلون الفرع (الإمارات أحمر · عمان
       برتقالي · السعودية أخضر) — بداخله مجسّم البيت الذهبي فقط
       (بلا أي صورة) بنفس طول كرت الخريطة — الضغط عليه يفتح
       موقع الوكلاء على Google Maps. بجانبه يميناً مربع العنوان.
     · شريط المواعيد عرضي كبير ثم لا شيء — صندوق «تفضّل بزيارتنا»
       حُذف بأمر المالك.
   ★ الصورة الحالية (الرفوف الذهبية) مؤقتة حتى تصل صور الفروع.
   ★ روابط المواقع النهائية تصل لاحقاً — الآن عناوين مؤقتة.
   ============================================================ */

import { useState } from "react";
import { usePageMeta } from "../usePageMeta.js";
import { useAppSelector } from "../redux/hooks.js";
import { tr2 } from "../i18n.js";
import { Icon, Flag } from "../components/Source/Icons.jsx";

/* ★ مجسّم البيت الذهبي داخل الإطار (بدل أي صورة — بأمر المالك) */
function HouseMock() {
  return (
    <svg
      viewBox="0 0 120 112"
      aria-hidden="true"
      focusable="false"
      style={{ width: "92px", height: "86px", flex: "0 0 auto" }}
      fill="none"
      stroke="#d9b877"
      strokeWidth="3.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M14 56 L60 16 L106 56" />
      <path d="M26 50 V96 H94 V50" />
      <path d="M52 96 V74 H68 V96" />
      <path d="M84 30 L94 20" />
      <path d="M90 36 L100 26" />
      <rect x="34" y="62" width="4" height="4" fill="#d9b877" stroke="none" />
      <rect x="42" y="62" width="4" height="4" fill="#d9b877" stroke="none" />
      <rect x="34" y="70" width="4" height="4" fill="#d9b877" stroke="none" />
      <rect x="42" y="70" width="4" height="4" fill="#d9b877" stroke="none" />
    </svg>
  );
}

/* ★ الفروع الثلاثة — عناوين مؤقتة؛ mapLink الفارغ = بحث Google عن العنوان.
   روابط المالك الحقيقية توضع هنا (mapLink + embedQuery). */
const BRANCHES = [
  {
    key: "SA",
    flag: "sa",
    accent: "#1a7a4a",
    frameOuter: "linear-gradient(135deg,#0d3d22 0%,#1a7a4a 25%,#145c36 50%,#239a55 75%,#0b3320 100%)",
    frameEdge: "#14663a",
    countryAr: "السعودية",
    countryEn: "Saudi Arabia",
    branchAr: "فرع السعودية",
    branchEn: "Saudi branch",
    addressAr: "الرياض، المملكة العربية السعودية",
    addressEn: "Riyadh, Saudi Arabia",
    mapLink: "",
    embedQuery: "Riyadh, Saudi Arabia",
    hoursAr: "يومياً · 9 صباحاً – 11 مساءً",
    hoursEn: "Daily · 9:00 – 23:00"
  },
  {
    key: "OM",
    flag: "om",
    accent: "#b35a1e",
    frameOuter: "linear-gradient(135deg,#6e2f0e 0%,#b35a1e 25%,#8f4a16 50%,#c97a2a 75%,#5f2a0c 100%)",
    frameEdge: "#9a5416",
    countryAr: "عمان",
    countryEn: "Oman",
    branchAr: "فرع عمان",
    branchEn: "Oman branch",
    addressAr: "مسقط، سلطنة عمان",
    addressEn: "Muscat, Oman",
    mapLink: "",
    embedQuery: "Muscat, Oman",
    hoursAr: "يومياً · 10 صباحاً – 10 مساءً",
    hoursEn: "Daily · 10:00 – 22:00"
  },
  {
    key: "AE",
    flag: "ae",
    accent: "#8f1d22",
    frameOuter: "linear-gradient(135deg,#7a1418 0%,#b03a2e 25%,#8f1d22 50%,#c0392b 75%,#6e1216 100%)",
    frameEdge: "#a93226",
    countryAr: "الإمارات",
    countryEn: "UAE",
    branchAr: "فرع الإمارات",
    branchEn: "UAE branch",
    addressAr: "دبي، دولة الإمارات العربية المتحدة",
    addressEn: "Dubai, United Arab Emirates",
    mapLink: "",
    embedQuery: "Dubai, United Arab Emirates",
    hoursAr: "يومياً · 10 صباحاً – 10 مساءً",
    hoursEn: "Daily · 10:00 – 22:00"
  }
];

function mapsSearchUrl(address) {
  return "https://www.google.com/maps/search/?api=1&query=" + encodeURIComponent(address);
}

function mapsEmbedUrl(query) {
  return "https://www.google.com/maps?q=" + encodeURIComponent(query) + "&output=embed";
}

/* وردة محفورة ذهبية على الإطار (بلا قلوب) */
function Ornament({ style }) {
  return (
    <span
      aria-hidden="true"
      style={{
        position: "absolute",
        color: "#f3d27a",
        textShadow: "0 1px 2px rgba(0,0,0,.7), 0 0 6px rgba(243,210,122,.45)",
        lineHeight: 1,
        pointerEvents: "none",
        ...style
      }}
    >
      ❀
    </span>
  );
}

/* أيقونة صغيرة أفقية (15px) */
function SmIcon({ name, strokeWidth }) {
  return (
    <span className="br-ico" aria-hidden="true">
      <Icon name={name} strokeWidth={strokeWidth || 2} />
    </span>
  );
}

export default function BranchesPage() {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const isEn = language === "en";
  const [sel, setSel] = useState("AE");
  usePageMeta({
    route: "branches",
    titleAr: "وكلاءنا",
    titleEn: "Our agents"
  });

  const branch = BRANCHES.filter(function (b) { return b.key === sel; })[0] || BRANCHES[2];
  const innerDir = isEn ? "ltr" : "rtl";
  const goMap = function () {
    try {
      window.open(branch.mapLink || mapsSearchUrl(isEn ? branch.addressEn : branch.addressAr), "_blank", "noopener,noreferrer");
    } catch (e) {}
  };

  return (
    <section className="container view inf" id="infoView" style={{ paddingTop: 0 }}>
      <style>{`
        .br-tabs{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:5px 0 10px}
        .br-tab{display:inline-flex;align-items:center;gap:8px;padding:6px 18px;border-radius:999px;border:1.5px solid var(--line);background:var(--surface);cursor:pointer;font-weight:800;font-size:14px;color:var(--fg)}
        .br-tab .br-flag{width:24px;height:16px;border-radius:3px;overflow:hidden;border:1px solid var(--line-soft);flex:0 0 auto}
        .br-tab .br-flag svg{display:block;width:100%;height:100%}
        .br-tab.on{color:#fff;border-color:transparent}
        .br-ico{display:inline-flex;width:15px;height:15px;flex:0 0 auto;vertical-align:-2px}
        .br-ico svg{width:100%;height:100%;display:block}
        .br-hours{display:flex;align-items:center;justify-content:center;gap:8px 28px;flex-wrap:wrap;text-align:center}
        .br-hours .br-h{font-size:20px;font-weight:800;color:var(--gold-3,#b08a2e)}
        .br-hours .br-t{font-size:14px;display:inline-flex;align-items:center;gap:6px}
      `}</style>

      {/* ★ ليبل وكلاءنا — ملاصق للأعلى (نلغي padding قالب inf-hero) */}
      <header className="inf-hero" style={{ marginBottom: 0, padding: "0 0 4px" }}>
        <h1 className="inf-h1" style={{ fontSize: "26px", margin: 0 }}>
          {isEn ? (
            <span>
              Our <span className="gold-text">agents</span>
            </span>
          ) : (
            <span>
              وكلا<span className="gold-text">ءنا</span>
            </span>
          )}
        </h1>
      </header>

      <div className="inf-body" style={{ maxWidth: "1180px", margin: "0 auto" }}>
        {/* ★ أزرار الدول — أسفل الليبل بـ5px */}
        <div className="br-tabs" role="tablist" aria-label={isEn ? "Countries" : "الدول"}>
          {BRANCHES.map(function (b) {
            const on = b.key === sel;
            return (
              <button
                key={b.key}
                role="tab"
                aria-selected={on}
                type="button"
                className={"br-tab" + (on ? " on" : "")}
                style={on ? { background: b.accent } : null}
                onClick={function () { setSel(b.key); }}
              >
                <span className="br-flag">
                  <Flag code={b.flag} />
                </span>
                <span>{isEn ? b.countryEn : b.countryAr}</span>
              </button>
            );
          })}
        </div>

        {/* ★ الصف: الإطار (يسار) + مربع العنوان (يمين) */}
        <div
          style={{
            display: "flex",
            gap: "18px",
            flexWrap: "wrap",
            direction: "ltr",
            alignItems: "stretch"
          }}
        >
          <div style={{ flex: "1.65 1 540px", minWidth: 0, direction: innerDir, display: "flex", flexDirection: "column" }}>
            <button
              type="button"
              onClick={goMap}
              title={isEn ? "Open our agents location on Google Maps" : "افتح موقع وكلائنا على خرائط جوجل"}
              style={{ display: "flex", flexDirection: "column", flex: 1, width: "100%", padding: 0, border: "none", background: "none", cursor: "pointer" }}
            >
              {/* الإطار بلون الفرع — مجسّم البيت فقط، بنفس طول كرت الخريطة */}
              <span
                style={{
                  display: "flex",
                  flexDirection: "column",
                  flex: 1,
                  position: "relative",
                  padding: "20px",
                  borderRadius: "10px",
                  background: branch.frameOuter,
                  border: "4px outset " + branch.frameEdge,
                  boxShadow: "inset 0 2px 6px rgba(255,255,255,.35), inset 0 -5px 12px rgba(0,0,0,.55), inset 5px 0 10px rgba(0,0,0,.35), inset -5px 0 10px rgba(0,0,0,.35), 0 12px 30px rgba(0,0,0,.45)"
                }}
              >
                <Ornament style={{ top: "2px", insetInlineStart: "6px", fontSize: "26px" }} />
                <Ornament style={{ top: "2px", insetInlineEnd: "6px", fontSize: "26px" }} />
                <Ornament style={{ bottom: "0px", insetInlineStart: "6px", fontSize: "26px" }} />
                <Ornament style={{ bottom: "0px", insetInlineEnd: "6px", fontSize: "26px" }} />
                <span
                  style={{
                    display: "flex",
                    flex: 1,
                    border: "2px solid #e8c66a",
                    borderRadius: "5px",
                    padding: "8px",
                    boxShadow: "0 0 0 1px rgba(0,0,0,.5), 0 0 10px rgba(232,198,106,.35)"
                  }}
                >
                  <span
                    style={{
                      display: "flex",
                      flex: 1,
                      alignItems: "center",
                      justifyContent: "center",
                      gap: "18px",
                      background: "#141114",
                      borderRadius: "2px",
                      padding: "28px 20px",
                      minHeight: "300px"
                    }}
                  >
                    <HouseMock />
                    <span style={{ textAlign: "center" }}>
                      <span style={{ display: "block", color: "#e8e8e8", fontWeight: 800, fontSize: "21px", lineHeight: 1.9 }}>
                        {isEn ? "Our agents are getting ready" : "وكلاؤنا قيد التجهيز"}
                      </span>
                      <span style={{ display: "block", color: "#9a9a9a", fontSize: "15px" }}>
                        {isEn ? "We will announce the opening here soon." : "سنعلن عن الافتتاح هنا قريباً."}
                      </span>
                    </span>
                  </span>
                </span>
              </span>
            </button>
            <p style={{ textAlign: "center", fontSize: "12.5px", opacity: 0.75, margin: "8px 0 0" }}>
              {tr2(language, "Tap the frame to open our agents location on Google Maps", "اضغط على الإطار لفتح موقع وكلاءنا على خرائط جوجل")}
            </p>
          </div>

          {/* ★ مربع العنوان — يمين */}
          <div style={{ flex: "1 1 300px", minWidth: 0, direction: innerDir }}>
            <div className="ct-empty" style={{ padding: "14px 16px", textAlign: "start" }}>
              <h3 style={{ margin: "0 0 4px" }}>{isEn ? branch.branchEn : branch.branchAr}</h3>
              <p style={{ fontSize: "16px", fontWeight: 800, margin: "0 0 8px" }}>
                <b>{isEn ? branch.addressEn : branch.addressAr}</b>
              </p>
              <iframe
                title={isEn ? branch.branchEn : branch.branchAr}
                src={mapsEmbedUrl(branch.embedQuery)}
                style={{ width: "100%", height: "170px", border: 0, borderRadius: "12px" }}
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
                allowFullScreen
              />
              <div className="wl-empty-actions" style={{ justifyContent: "center", marginTop: "10px", flexWrap: "wrap", gap: "8px" }}>
                <button className="btn-primary" type="button" onClick={goMap}>
                  <Icon name="truck" strokeWidth={1.8} />
                  <span>{tr2(language, "Take me to the location", "انتقل إلى الموقع")}</span>
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* ★ شريط المواعيد — عرضي كبير */}
        <div className="ct-empty" style={{ padding: "12px 18px", marginTop: "14px" }}>
          <div className="br-hours">
            <span className="br-t"><SmIcon name="clock" />{tr2(language, "Opening hours", "مواعيد الفتح والإغلاق")}</span>
            <span className="br-h">{isEn ? branch.hoursEn : branch.hoursAr}</span>
            <span className="br-t"><SmIcon name="check" />{tr2(language, "Original 100% — sealed with warranty", "أصلي 100% — مختوم مع ضمان")}</span>
            <span className="br-t"><SmIcon name="check" />{tr2(language, "Try before you buy", "جرّب قبل أن تشتري")}</span>
          </div>
        </div>
      </div>
    </section>
  );
}
